import assert from "node:assert/strict";
import test from "node:test";

import {
  PATCHED_TAIL,
  postprocessMcpSource,
  RAW_TAIL,
} from "./postprocess-mcp-attestation.mjs";

const BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.\n";
const PREFIX = `${BANNER}// generated MCP business bundle\n`;

test("canonical generated output receives the exact wrapper", () => {
  const result = postprocessMcpSource(PREFIX + RAW_TAIL);

  assert.equal(result.changed, true);
  assert.equal(result.output, PREFIX + PATCHED_TAIL);
  assert.equal(result.output.match(/Deno\.serve/g)?.length, 1);
  assert.equal(
    result.output.match(/DYNAMIC_RUNTIME_ATTESTATION_BEGIN/g)?.length,
    1,
  );
});

test("postprocessing is byte-idempotent", () => {
  const patched = PREFIX + PATCHED_TAIL;
  const result = postprocessMcpSource(patched);

  assert.equal(result.changed, false);
  assert.equal(result.output, patched);
});

test("check mode accepts only the exact wrapped tail", () => {
  assert.equal(
    postprocessMcpSource(PREFIX + PATCHED_TAIL, { check: true }).changed,
    false,
  );
  assert.throws(
    () => postprocessMcpSource(PREFIX + RAW_TAIL, { check: true }),
    /missing the exact attestation wrapper/,
  );
});

test("generator drift and partial markers fail closed", () => {
  assert.throws(
    () => postprocessMcpSource(`${PREFIX}${RAW_TAIL} // drift\n`),
    /shape changed/,
  );
  assert.throws(
    () => postprocessMcpSource(`${PREFIX}// DYNAMIC_RUNTIME_ATTESTATION_BEGIN\n${RAW_TAIL}`),
    /partial attestation wrapper/,
  );
});

test("missing ownership banner and reserved collisions fail closed", () => {
  assert.throws(
    () => postprocessMcpSource(`// user-owned\n${RAW_TAIL}`),
    /no longer owned/,
  );
  assert.throws(
    () => postprocessMcpSource(
      "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
        RAW_TAIL,
    ),
    /no longer owned/,
  );
  assert.throws(
    () => postprocessMcpSource(`${PREFIX}const __dynamicMcpBusinessHandler = 1;\n${RAW_TAIL}`),
    /collides/,
  );
});
